// Formats payload for Meta Cloud API (WhatsApp Business Platform)
const body = $input.first()?.json?.body || $input.first()?.json || {};

const recipientPhone = (body.customerPhone || body.phone || '').replace(/[^0-9]/g, '');
const stageNumber = Number(body.stageNumber || body.stage || 1);
const customerName = body.customerName || 'Valued Customer';
const businessName = body.businessName || 'Kavach Mobile Accessories';
const invoiceNumber = body.invoiceNumber || 'INV-2026-001';
const amountFormatted = body.amountFormatted || '10,000';
const dueDate = body.dueDate || '2026-11-20';
const payUrl = body.payUrl || 'https://duemitra.in/pay';
const contactPerson = body.contactPerson || 'Accounts Officer (+91 98230 12345)';
const overdueDays = String(body.overdueDays || 5);
const lang = body.language || 'en'; // 'en', 'hi', 'mr'

// 5 Official Meta Utility Templates
const templateMapping = {
  1: {
    name: 'friendly_pre_due_heads_up',
    parameters: [
      { type: 'text', text: customerName },
      { type: 'text', text: businessName },
      { type: 'text', text: invoiceNumber },
      { type: 'text', text: amountFormatted },
      { type: 'text', text: dueDate },
      { type: 'text', text: payUrl },
      { type: 'text', text: contactPerson }
    ]
  },
  2: {
    name: 'invoice_due_today_advisory',
    parameters: [
      { type: 'text', text: customerName },
      { type: 'text', text: invoiceNumber },
      { type: 'text', text: amountFormatted },
      { type: 'text', text: businessName },
      { type: 'text', text: dueDate },
      { type: 'text', text: payUrl },
      { type: 'text', text: contactPerson }
    ]
  },
  3: {
    name: 'first_overdue_followup',
    parameters: [
      { type: 'text', text: customerName },
      { type: 'text', text: invoiceNumber },
      { type: 'text', text: amountFormatted },
      { type: 'text', text: businessName },
      { type: 'text', text: overdueDays },
      { type: 'text', text: dueDate },
      { type: 'text', text: payUrl },
      { type: 'text', text: contactPerson }
    ]
  },
  4: {
    name: 'second_overdue_warning',
    parameters: [
      { type: 'text', text: customerName },
      { type: 'text', text: invoiceNumber },
      { type: 'text', text: amountFormatted },
      { type: 'text', text: businessName },
      { type: 'text', text: overdueDays },
      { type: 'text', text: payUrl },
      { type: 'text', text: contactPerson }
    ]
  },
  5: {
    name: 'commercial_demand_heads_up',
    parameters: [
      { type: 'text', text: customerName },
      { type: 'text', text: invoiceNumber },
      { type: 'text', text: amountFormatted },
      { type: 'text', text: businessName },
      { type: 'text', text: overdueDays },
      { type: 'text', text: payUrl },
      { type: 'text', text: contactPerson }
    ]
  }
};

const selected = templateMapping[stageNumber] || templateMapping[1];

const metaPayload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: recipientPhone.startsWith('91') ? recipientPhone : `91${recipientPhone}`,
  type: 'template',
  template: {
    name: selected.name,
    language: { code: lang === 'mr' ? 'mr' : lang === 'hi' ? 'hi' : 'en_US' },
    components: [
      {
        type: 'body',
        parameters: selected.parameters
      }
    ]
  }
};

return [{
  json: {
    recipientPhone: metaPayload.to,
    templateName: selected.name,
    metaPayload,
    isConfigured: Boolean(process.env.META_ACCESS_TOKEN && process.env.META_PHONE_NUMBER_ID)
  }
}];
